/**
 * An immutable, separately identified PHYSICAL re-declaration after BOTH
 * players consented to reconsider a disputed leader-casualty die roll.
 * Fixture-only; no dice generated by this module, no effects applied.
 */
import {createHash} from 'node:crypto';

const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i;
const FACES=new Set(['LIGHT','MEDIUM','HEAVY','LEADER','FLAG','SWORDS']);
const exact=(x,keys)=>x!==null&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).length===keys.length&&keys.every(k=>Object.hasOwn(x,k));
const hash=x=>createHash('sha256').update(x).digest('hex');

export const LAB_LEADER_REROLL_ATTEMPT_KIND='LAB_PHYSICAL_LEADER_REROLL_DECLARATION_V1';
export const leaderRerollId=reservationId=>'lab_reroll_leader_'+reservationId.replaceAll('-','')+'_1';

/** Verify the new declaration WITHOUT treating it as accepted or executable. */
export function inspectLabLeaderRerollAttempt({attempt,reservationId,originalRollDigestSha256,
  attackerSide,diceCount,consentRevision,currentRevision}={}) {
  if(!exact(attempt,['kind','createdRevision','originalRollDigestSha256','roll']) ||
      attempt.kind!==LAB_LEADER_REROLL_ATTEMPT_KIND ||
      !UUID.test(String(reservationId)) || !['A','B'].includes(attackerSide) ||
      ![1,2].includes(diceCount) ||
      !Number.isSafeInteger(consentRevision) || consentRevision<0 ||
      !Number.isSafeInteger(currentRevision) ||
      currentRevision!==consentRevision+1 || attempt.createdRevision!==currentRevision ||
      !/^[a-f0-9]{64}$/.test(String(originalRollDigestSha256)) ||
      attempt.originalRollDigestSha256!==originalRollDigestSha256) return null;
  const r=attempt.roll;
  if(!exact(r,['type','purpose','ruleset','rollId','actor','source','verification',
      'diceCount','results','attackAuthorized','combatResolved','needsFullLegalityCheck']) ||
      r.type!=='ANCIENTS_BASE_LEADER_CASUALTY_CAPTURED' ||
      r.purpose!=='LEADER_CASUALTY_CHECK' || r.ruleset!=='ancients-base-3e-2009' ||
      r.rollId!==leaderRerollId(reservationId) || r.actor!==attackerSide ||
      r.source!=='PHYSICAL' || r.verification!=='PLAYER_DECLARED' ||
      r.diceCount!==diceCount || !Array.isArray(r.results) ||
      r.results.length!==diceCount || r.results.some(face=>!FACES.has(face)) ||
      r.attackAuthorized!==false || r.combatResolved!==false ||
      r.needsFullLegalityCheck!==true) return null;
  return Object.freeze({status:'PHYSICAL_REROLL_AWAITING_OPPONENT',
    createdRevision:attempt.createdRevision,declaredDiceCount:r.diceCount,
    newRollDigestSha256:hash(JSON.stringify(r)),
    originalUnchanged:true,opponentConfirmed:false,combatAuthorized:false});
}
